/*
 * Haldi & Mehendi — one card split on a diagonal. Upper-left: Haldi (marigold, saffron, ivory)
 * with a toran, marigold ladis and a brass urli; Rishabh stands here. Lower-right: Mehendi
 * (emerald, deep green, gold) with a cusped arch, bolsters, cones and a large hand whose
 * mehendi draws itself; Nandita stands here. A scalloped gold edge joins the two papers.
 */

const SVG: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <svg
    width={1080}
    height={1920}
    viewBox="0 0 1080 1920"
    style={{ position: "absolute", inset: 0, overflow: "visible" }}
  >
    {children}
  </svg>
);

// the diagonal: from the left edge (0, D0) up to the right edge (1080, D1)
const D0 = 1500;
const D1 = 620;

const scallopEdge = (n: number): string => {
  let d = `M-40 ${D0 + (D0 - D1) * (40 / 1080)}`;
  d += ` L0 ${D0}`;
  for (let i = 1; i <= n; i++) {
    const x = (1080 * i) / n;
    const y = D0 + ((D1 - D0) * i) / n;
    const seg = Math.hypot(1080 / n, (D0 - D1) / n);
    d += ` A${(seg * 0.56).toFixed(1)} ${(seg * 0.56).toFixed(1)} 0 0 1 ${x.toFixed(1)} ${y.toFixed(1)}`;
  }
  return d;
};
const EDGE = scallopEdge(24);
const MEHENDI_CARD = `${EDGE} L1120 ${D1 - 40} L1120 1960 L-40 1960 Z`;

const R_X = 390;
const R_FEET = 1150;
const N_X = 620;
const N_FEET = 1512;
const FIG = 590;

